<?php require_once __DIR__.'/../app/layout.php';$types=$pdo->query('SELECT * FROM membership_types WHERE is_active=1 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$mobile=preg_replace('/\D/','',$_POST['mobile']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';$typeId=(int)($_POST['membership_type_id']??0);$s=$pdo->prepare('SELECT id FROM membership_types WHERE id=? AND is_active=1');$s->execute([$typeId]);if(strlen($name)<2||!preg_match('/^\d{10,15}$/',$mobile)||!$email||strlen($password)<8||!$s->fetch())flash('Complete all fields and choose a membership type.','error');else{try{$pdo->prepare('INSERT INTO members (full_name,mobile,email,password_hash,membership_type_id) VALUES (?,?,?,?,?)')->execute([$name,$mobile,$email,password_hash($password,PASSWORD_DEFAULT),$typeId]);$_SESSION['member_id']=(int)$pdo->lastInsertId();flash('Registration submitted. Please pay the membership fee to complete your request.');redirect('/member/payment.php?registration=1');}catch(PDOException $e){flash('That email address or mobile number is already registered.','error');}}}
header_html('Membership registration');?><style>body:has(.membership-register){background:linear-gradient(90deg,#fff9f0d9,#ffffffd9),url('/assets/membership-background.png') center/cover fixed}.membership-register{max-width:460px;margin:clamp(20px,6vh,70px) auto;padding:32px;background:#fffffff2;border:1px solid #ffffff;border-radius:18px;box-shadow:0 18px 50px #102a5240}.membership-register h1{margin:0;font-size:2.2rem;text-align:center}.membership-register .intro{text-align:center;margin:8px 0 24px;color:#586579}.membership-register form{padding:0;background:transparent;border:0;box-shadow:none}.membership-register label{font-size:.92rem;font-weight:700}.membership-register input{margin-bottom:12px}.membership-register button{width:100%;margin-top:8px}.membership-register .login-link{text-align:center;margin:18px 0 0;font-size:.9rem}</style><section class="membership-register"><h1>Join TSSMT</h1><p class="intro">Become part of a community dedicated to preserving Talcher’s freedom-fighter legacy.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Membership Type<select name="membership_type_id" required><option value="">Choose membership type</option><?php foreach($types as $type):?><option value="<?=$type['id']?>"><?=e($type['name'])?> — ₹<?=e($type['fee'])?> (<?=e($type['validity'])?>)</option><?php endforeach;?></select></label><label>Full Name<input name="full_name" required maxlength="150" autocomplete="name"></label><label>Mobile Number<input name="mobile" inputmode="numeric" required autocomplete="tel"></label><label>Email Address<input type="email" name="email" required autocomplete="email"></label><label>Create Password<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><button>Continue to fee payment</button></form><p class="login-link">Already a member? <a href="/login.php">Sign in</a></p></section><?php footer_html();
